// Browser-only stand-in for the Tauri backend so the UI can be developed with `npm run dev`.
// Loads src/dev/snapshot.json if present (generated by the `real_machine` smoke test with SKILLSHELF_DUMP).

import type {
  ActionRequest,
  AppUpdate,
  Changelog,
  CheckResult,
  DownloadProgress,
  Environment,
  Item,
  JobEvent,
  LastRun,
  McpReport,
  Readme,
  Risk,
  ScanResult,
  CloneStatus,
  Settings,
  TraySummary,
  Usage,
  UsageProgress,
  UsageReport,
} from "../types";

const snapshots = import.meta.glob<{ default: CheckResult }>("./snapshot.json");
const listeners = new Set<(e: JobEvent) => void>();
const usageListeners = new Set<(p: UsageProgress) => void>();
const lastRuns: Record<string, LastRun> = {};
let items: Item[] = [];
let settings: Settings = { projects: [], autoCheck: true, checkInterval: "daily", closeToTray: true, notifications: true };
let autostart = false;
let job = 1;
/** Set by Stop; jobs that haven't finished yet end as cancelled. */
let stopped = false;
const wait = (ms: number) => new Promise((r) => setTimeout(r, ms));

/** Fills fields an older snapshot doesn't have, and marks two skills moved/removed upstream so those states show. */
async function load(): Promise<Item[]> {
  const loader = snapshots["./snapshot.json"];
  const loaded: Item[] = loader ? (await loader()).default.items : [];
  const items = loaded.map((i) => ({ ...i, isMod: i.isMod ?? false, cost: i.cost ?? null, issues: i.issues ?? [], upstream: i.upstream ?? null }));
  const cli = items.filter((i) => i.source === "skillsCli" && i.status === "upToDate");
  if (cli[1]) {
    const repo = cli[1].origin ?? "example/skills";
    Object.assign(cli[1], {
      status: "moved",
      statusDetail: `Moved upstream to ${repo}/skills/${cli[1].name}. Reinstall to keep getting updates.`,
      upstream: { repo, folder: `skills/${cli[1].name}`, commit: null },
    });
  }
  if (cli[2]) {
    const repo = cli[2].origin ?? "example/skills";
    const s = sha(cli[2].id, 9);
    Object.assign(cli[2], {
      status: "removed",
      statusDetail: `Deleted upstream in ${s.slice(0, 12)}: Remove deprecated skills`,
      upstream: { repo, folder: null, commit: { sha: s, date: hoursAgo(80), message: "Remove deprecated skills", url: `https://github.com/${repo}/commit/${s}` } },
    });
  }
  return items;
}

/** Same pseudo-random numbers for an item on every call. */
function seeded(seed: string) {
  let h = 2166136261;
  for (const c of seed) h = Math.imul(h ^ c.charCodeAt(0), 16777619);
  return () => ((h = Math.imul(h ^ (h >>> 15), 2246822507) >>> 0) % 1000) / 1000;
}

function mockUsage(item: Item): Usage {
  const rnd = seeded(item.id);
  const idle = rnd() < 0.35; // about a third unused, so Clean Up has something to show
  const daily = Array.from({ length: 30 }, () => (idle ? 0 : rnd() < 0.6 ? 0 : Math.round(rnd() * 12)));
  const uses = daily.reduce((a, b) => a + b, 0);
  const lastDay = daily.reduce((last, n, i) => (n > 0 ? i : last), -1);
  const lastUsed = lastDay >= 0 ? hoursAgo((29 - lastDay) * 24 + 3) : rnd() < 0.5 ? hoursAgo(24 * 45) : null;
  return { uses, lastUsed, daily };
}

const sampleRisks: Risk[] = [
  { kind: "hooks", files: ["hooks/hooks.json"], why: "Hooks run commands automatically on Claude Code events, without asking first." },
  {
    kind: "scripts",
    files: ["hooks/session-start.mjs", "scripts/install.sh"],
    why: "Scripts and programs can run on your computer when the plugin or skill uses them.",
  },
];

const hoursAgo = (h: number) => new Date(Date.now() - h * 3_600_000).toISOString();
const sha = (seed: string, n: number) =>
  Array.from({ length: 40 }, (_, i) => "0123456789abcdef"[(seed.charCodeAt(i % seed.length) * (i + 7) + n * 31) % 16]).join("");
const commits = (repo: string, seed: string, messages: string[]) =>
  messages.map((message, n) => {
    const s = sha(seed, n);
    return { sha: s, date: hoursAgo(6 + n * 19), message, url: `https://github.com/${repo}/commit/${s}` };
  });
let rateLimitedOnce = false;

/** Sample changelogs covering each state the detail panel can show. */
function mockChangelog(item: Item): Changelog {
  const empty = {
    label: "",
    entries: [],
    total: 0,
    sections: [],
    sectionsLabel: null,
    moreUrl: null,
    note: null,
    retryable: false,
    risks: null,
    installed: null,
  };
  if (item.source === "synced")
    return { ...empty, note: "Your claude.ai organization updates this plugin and doesn't publish what changed." };
  if (item.source === "local" || item.source === "project")
    return { ...empty, note: "No installer tracks this skill, so there's no upstream history to compare with." };
  if (item.source === "marketplace") {
    const repo = item.repoUrl?.replace("https://github.com/", "") ?? "example/marketplace";
    const sections = [
      {
        version: item.latest,
        title: `${item.latest} (2026-10-15)`,
        body: [
          "### Features",
          "- **router:** route cost questions to the `cost-audit` lane",
          "- Add golden path for serverless ComfyUI ([#86](https://github.com/example/repo/pull/86))",
          "",
          "### Bug Fixes",
          "- Retry pod creation when capacity is briefly unavailable",
        ].join("\n"),
      },
      {
        version: "1.7.3",
        title: "1.7.3 (2026-10-14)",
        body: "### Documentation\n- Clarify how network volumes attach to serverless workers",
      },
      { version: "1.7.0", title: "1.7.0 (2026-10-09)", body: "### Features\n- Bundle the hosted MCP server" },
      { version: "1.6.0", title: "1.6.0 (2026-10-08)", body: "- Template repair for ComfyUI workflows" },
    ];
    if (item.name.includes("ui-ux"))
      return {
        ...empty,
        label: "Commits in the marketplace that touched this plugin",
        sections: sections.slice(0, 2),
        sectionsLabel: "CHANGELOG.md",
        note: "The installed commit isn't in the local marketplace copy, so Skillshelf can't tell which commits are new.",
      };
    const entries = commits(repo, item.id, [
      "docs(model-caching): load volume-backed models via VolumeCache (#86)",
      "feat(router): send cost questions to the cost-audit lane",
      "fix(pod-doctor): read worker logs before restarting a pod",
      "chore(release): 1.7.3",
      "docs: explain network volume regions",
      "feat(templates): repair missing ComfyUI custom nodes",
      "fix(flash): pass the endpoint id through to job polling",
      "refactor: share the GPU catalog lookup between lanes",
      "test: cover serverless golden paths",
      "chore(release): 1.7.0",
    ]);
    return {
      ...empty,
      label: "Commits in the marketplace that touched this plugin",
      entries,
      total: 26,
      sections: item.name.includes("understand") ? [] : sections,
      sectionsLabel: "CHANGELOG.md",
      moreUrl: `https://github.com/${repo}/commits/HEAD/plugins/${item.name}`,
      risks: item.name.includes("runpod") ? sampleRisks : [],
    };
  }
  if (item.source === "skillsCli") {
    if (item.name === "scenario-godot-expert" && !rateLimitedOnce) {
      rateLimitedOnce = true;
      throw "GitHub rate limit reached. Sign in with `gh auth login` or set GITHUB_TOKEN.";
    }
    const repo = item.origin ?? "example/skills";
    const all = [
      "chore(skills): storyboards are a board of stills with one page format (#5599)",
      "fix(skills): reject occlusion timeout before verdict (#5491)",
      "feat(cli): save check, snapshot and render artifacts per revision (#5522)",
      "docs(skills): fix frame-worker contract, lint codes and stale references (#5515)",
    ];
    const listed = commits(repo, item.id, all);
    const n = 1 + (item.name.length % (all.length - 1));
    const entries = listed.slice(0, n);
    return {
      ...empty,
      label: "Commits to this skill since your version",
      entries,
      total: entries.length,
      moreUrl: `https://github.com/${repo}/commits/HEAD/skills/${item.name}`,
      installed: listed[n],
      risks:
        item.name.length % 3 === 0
          ? [
              {
                kind: "allowedTools",
                files: ["SKILL.md"],
                why: "Tools listed in a skill's allowed-tools run without a permission prompt. SKILL.md adds Bash(npx:*).",
              },
            ]
          : [],
    };
  }
  return { ...empty, note: "There's nothing to compare this item against." };
}

export const mockApi = {
  scan: async (): Promise<ScanResult> => {
    await wait(400);
    // Like scan::keep_verdicts: an item found again at the same version keeps its last check.
    items = (await load()).map((i) => {
      const p = items.find((p) => p.id === i.id && p.version === i.version && p.status !== "unchecked");
      return p
        ? { ...i, status: p.status, latest: p.latest, statusDetail: p.statusDetail, upstream: p.upstream }
        : { ...i, status: "unchecked", latest: null, statusDetail: null };
    });
    return { items, warnings: [], scannedAt: Date.now() };
  },
  checkUpdates: async (): Promise<CheckResult> => {
    await wait(1200);
    const checked = await load();
    items = items.map((i) => checked.find((c) => c.id === i.id) ?? i);
    return { items, warnings: [], checkedAt: Date.now() };
  },
  // Jobs run one after another, 1.2 s each, like the real queue.
  runActions: async (requests: ActionRequest[]) => {
    stopped = false;
    requests.forEach((r, n) => {
      const item = items.find((i) => i.id === r.itemId)!;
      const base = { jobId: job++, itemId: item.id, itemName: item.name, action: r.action, line: null, message: null, confirm: null };
      const emit = (e: Partial<JobEvent>, ms: number) =>
        setTimeout(() => {
          const ending = e.state === "success" || e.state === "failed";
          const event = stopped && ending ? { state: "cancelled" as const, message: "Stopped" } : e;
          if (stopped && (e.state === "running" || e.state === "log")) return;
          listeners.forEach((l) => l({ ...base, state: "queued", ...event }));
        }, ms);
      const start = n * 1200;
      emit({ state: "queued" }, 0);
      emit({ state: "running" }, start + 100);
      emit({ state: "log", line: `mock: ${r.action} ${item.name}` }, start + 500);
      const fails = item.name.includes("runpod");
      emit(fails ? { state: "failed", message: "Mock failure" } : { state: "success", message: "Done (mock)" }, start + 1200);
      lastRuns[item.id] = {
        action: r.action,
        state: fails ? "failed" : "success",
        message: fails ? "Mock failure" : "Done (mock)",
        lines: [`mock: ${r.action} ${item.name}`],
        finishedAt: Date.now() + start + 1200,
      };
    });
  },
  openFolder: async () => {},
  openRepo: async () => {},
  changelog: async (itemId: string): Promise<Changelog> => {
    await wait(500);
    return mockChangelog(items.find((i) => i.id === itemId)!);
  },
  openProjectPage: async (page: string) => {
    console.info("open project page", page);
  },
  openChangelogLink: async (_itemId: string, url: string) => {
    window.open(url, "_blank", "noopener");
  },
  mcpStatus: async (): Promise<McpReport> => {
    await wait(1500);
    const s = (plugin: string | null, name: string, target: string | null, transport: string | null, state: McpReport["servers"][number]["state"], reason: string | null = null) => ({
      plugin,
      claudeAi: false,
      name,
      target,
      transport,
      state,
      reason,
    });
    return {
      checkedAt: Date.now(),
      servers: [
        { ...s(null, "Claude Docs", "api.anthropic.com", null, "connected"), claudeAi: true },
        { ...s(null, "Atlassian MCP", "mcp.atlassian.com", null, "connected"), claudeAi: true },
        s("runpod", "runpod", "mcp.getrunpod.io", "HTTP", "connected"),
        s("pm-skills", "atlassian", "mcp.atlassian.com", "SSE", "needsAuth"),
        s("design", "figma", "mcp.figma.com", "HTTP", "needsAuth"),
        s("design", "google calendar", null, "HTTP", "notConfigured"),
        s("vgv-ai-flutter-plugin", "very-good-cli", "very_good", null, "failed", "CONNECTION_CLOSED: Connection closed"),
        s("data", "definite", "api.definite.app", "HTTP", "failed", "MCP endpoint not found at api.definite.app. Check the URL in your MCP config."),
        s("pdf-viewer", "pdf", "npx", null, "connected"),
        s(null, "rea", "node", null, "connected"),
        s(null, "blender", "uvx", null, "pending"),
      ],
    };
  },
  usage: async (): Promise<UsageReport> => {
    for (let read = 0; read <= 100; read += 20) {
      usageListeners.forEach((l) => l({ read, total: 100 }));
      await wait(150);
    }
    return { byItem: Object.fromEntries(items.map((i) => [i.id, mockUsage(i)])), files: 1007, indexedAt: Date.now() };
  },
  onUsageProgress: async (cb: (p: UsageProgress) => void) => {
    usageListeners.add(cb);
    return () => usageListeners.delete(cb);
  },
  readme: async (itemId: string): Promise<Readme | null> => {
    await wait(200);
    const item = items.find((i) => i.id === itemId);
    if (!item?.path) return null;
    const body = [
      `# ${item.name}`,
      "",
      item.description ?? "No description.",
      "",
      "## Usage",
      "",
      `- Run \`/${item.name}\` or ask Claude to use it.`,
      "- Works offline once installed.",
      "",
      "```bash",
      `claude plugin install ${item.name}`,
      "```",
    ].join("\n");
    return { file: item.kind === "skill" ? "SKILL.md" : "README.md", text: body, truncated: false };
  },
  lastRuns: async () => lastRuns,
  // Add ?clone to the URL to preview clone mode.
  cloneStatus: async (): Promise<CloneStatus | null> =>
    new URLSearchParams(location.search).has("clone")
      ? {
          dir: "C:\\Dev\\AI\\skillshelf",
          branch: "master",
          defaultBranch: "master",
          behind: 3,
          commits: ["b6fb380 Screens: Overview, Clean Up, MCP Servers", "0ab9a26 Updates experience: review sheet", "481b906 Backend data for v0.2"],
          blocked: null,
        }
      : null,
  cloneUpdate: async (onLine: (line: string) => void) => {
    for (const l of ["$ git pull --ff-only", "Fast-forward", "$ npm ci --no-audit --no-fund", "added 312 packages in 9s", "$ npm run tauri build -- --no-bundle"]) {
      await new Promise((r) => setTimeout(r, 600));
      onLine(l);
    }
    throw new Error("Mock: the build can't run in the browser preview");
  },
  stopActions: async () => {
    stopped = true;
  },
  // No tray in the browser; the title shows what the window title would.
  updateTray: async (s: TraySummary) => {
    document.title = s.tokens ? s.text["tray.title"].replace("{tokens}", `${Math.round(s.tokens / 1000)}k`) : "Skillshelf";
  },
  onTray: async () => () => {},
  onScheduledCheck: async () => () => {},
  getSettings: async () => settings,
  saveSettings: async (s: Settings) => {
    settings = s;
  },
  environment: async (): Promise<Environment> => ({
    claudeDir: "~/.claude",
    claude: "claude",
    npx: "npx",
    git: "git",
    gh: null,
    os: "browser",
    version: "dev",
    tray: true,
    autostart,
  }),
  setAutostart: async (on: boolean) => {
    autostart = on;
  },
  pickFolder: async () => null,
  onJob: async (cb: (e: JobEvent) => void) => {
    const listener = (e: JobEvent) => cb(e);
    listeners.add(listener);
    return () => listeners.delete(listener);
  },
  // No updater in the browser. Open the page with ?mockUpdate to preview the update banner.
  checkAppUpdate: async (): Promise<AppUpdate | null> => {
    await wait(300);
    if (!new URLSearchParams(location.search).has("mockUpdate")) return null;
    return {
      version: "0.2.0",
      currentVersion: "0.1.0",
      date: new Date().toISOString(),
      notes: `### Added

- In-app updates: Skillshelf checks for new versions and installs them.
- \`CHANGELOG.md\`

### Fixed

- A **mock** fix.`,
    };
  },
  installAppUpdate: async (onProgress: (p: DownloadProgress) => void) => {
    const total = 8_000_000;
    for (let downloaded = 0; downloaded <= total; downloaded += 800_000) {
      onProgress({ downloaded, total });
      await wait(150);
    }
    location.reload();
  },
};
